ALTER TABLE projects ADD COLUMN archived_at timestamptz;
CREATE TABLE intake_rounds(id uuid PRIMARY KEY,organization_id uuid NOT NULL,project_id uuid NOT NULL,name text NOT NULL,status text NOT NULL DEFAULT 'draft' CHECK(status IN('draft','open','closed')),opens_at timestamptz NOT NULL,closes_at timestamptz NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),version integer NOT NULL DEFAULT 1 CHECK(version>0),CHECK(closes_at>opens_at),FOREIGN KEY(organization_id,project_id) REFERENCES projects(organization_id,id),UNIQUE(organization_id,project_id,id));
ALTER TABLE intake_rounds ENABLE ROW LEVEL SECURITY;
ALTER TABLE intake_rounds FORCE ROW LEVEL SECURITY;
GRANT SELECT ON intake_rounds TO noxh_runtime;
CREATE POLICY round_scope ON intake_rounds FOR SELECT TO noxh_runtime USING(organization_id::text=current_setting('app.organization_id',true) AND project_id::text=current_setting('app.project_id',true));
CREATE SCHEMA identity_private;
REVOKE ALL ON SCHEMA identity_private FROM PUBLIC;
CREATE TABLE identity_private.zalo_settings(organization_id uuid PRIMARY KEY REFERENCES organizations(id),oa_id text NOT NULL,app_id text NOT NULL,template_id text NOT NULL,otp_parameter text NOT NULL,secret_cipher text NOT NULL,enabled boolean NOT NULL DEFAULT false,version integer NOT NULL DEFAULT 1,updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE identity_private.phone_challenges(id uuid PRIMARY KEY,organization_id uuid NOT NULL REFERENCES organizations(id),phone_ref text NOT NULL,phone_cipher text NOT NULL,otp_digest text NOT NULL,proof_digest text NOT NULL,status text NOT NULL CHECK(status IN('pending','sent','failed','superseded','locked','consumed','expired')),attempts integer NOT NULL DEFAULT 0 CHECK(attempts BETWEEN 0 AND 5),expires_at timestamptz NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX challenge_phone ON identity_private.phone_challenges(organization_id,phone_ref,created_at);
CREATE TABLE identity_private.phone_accounts(organization_id uuid NOT NULL,user_id uuid NOT NULL,phone_ref text NOT NULL,phone_cipher text NOT NULL,verified_at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(organization_id,phone_ref),FOREIGN KEY(organization_id,user_id) REFERENCES users(organization_id,id),UNIQUE(organization_id,user_id));
CREATE TABLE identity_private.citizen_sessions(token_hash text PRIMARY KEY,organization_id uuid NOT NULL,user_id uuid NOT NULL,expires_at timestamptz NOT NULL,revoked_at timestamptz,created_at timestamptz NOT NULL DEFAULT now(),FOREIGN KEY(organization_id,user_id) REFERENCES users(organization_id,id));
CREATE TABLE identity_private.auth_limits(key text PRIMARY KEY,window_at timestamptz NOT NULL,requests integer NOT NULL,last_request_at timestamptz NOT NULL);
CREATE TABLE identity_private.operations(id uuid PRIMARY KEY,organization_id uuid NOT NULL REFERENCES organizations(id),actor_ref text NOT NULL,action text NOT NULL,resource_ref text NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
CREATE FUNCTION identity_private.reject_event_change() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN RAISE EXCEPTION 'Operation events are append-only'; END $$;
CREATE TRIGGER immutable_operations BEFORE UPDATE OR DELETE ON identity_private.operations FOR EACH ROW EXECUTE FUNCTION identity_private.reject_event_change();
CREATE INDEX citizen_session_expiry ON identity_private.citizen_sessions(expires_at);
CREATE UNIQUE INDEX one_active_preparatory_dossier ON prep_dossiers(organization_id,project_id,owner_user_id) WHERE status='draft';
CREATE TABLE identity_private.revoked_staff_sessions(token_hash text PRIMARY KEY,expires_at timestamptz NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
